'use strict';

// MODULES //

var tape = require( 'tape' );
var isnanf = require( '@stdlib/math/base/assert/is-nanf' );
var Float32Array = require( '@stdlib/array/float32' );
var ndarray = require( '@stdlib/ndarray/base/ctor' );
var snanstdev = require( './../lib' );


// FUNCTIONS //

/**
* Returns a one-dimensional ndarray.
*
* @private
* @param {Collection} buffer - underlying data buffer
* @param {NonNegativeInteger} length - number of indexed elements
* @param {integer} stride - stride length
* @param {NonNegativeInteger} offset - index offset
* @returns {ndarray} one-dimensional ndarray
*/
function vector( buffer, length, stride, offset ) {
	return new ndarray( 'float32', buffer, [ length ], [ stride ], offset, 'row-major' );
}


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof snanstdev, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function has an arity of 1', function test( t ) {
	t.strictEqual( snanstdev.length, 1, 'has expected arity' );
	t.end();
});

tape( 'the function returns NaN for an empty ndarray', function test( t ) {
	var x = new Float32Array( [] );
	var v = snanstdev( [ vector( x, 0, 1, 0 ), 1 ] );

	t.strictEqual( isnanf( v ), true, 'returns NaN' );
	t.end();
});

tape( 'the function returns NaN when all values are NaN', function test( t ) {
	var x = new Float32Array( [ NaN, NaN, NaN ] );
	var v = snanstdev( [ vector( x, 3, 1, 0 ), 1 ] );

	t.strictEqual( isnanf( v ), true, 'returns NaN' );
	t.end();
});

tape( 'the function returns NaN when only one non-NaN value is present', function test( t ) {
	var x = new Float32Array( [ NaN, 2.0, NaN ] );
	var v = snanstdev( [ vector( x, 3, 1, 0 ), 1 ] );

	t.strictEqual( isnanf( v ), true, 'returns NaN' );
	t.end();
});

tape( 'the function computes the standard deviation for multiple non-NaN values', function test( t ) {
	var expected = 1.0;
	var x = new Float32Array( [ 1.0, 2.0, NaN, 3.0 ] );
	var v = snanstdev( [ vector( x, 4, 1, 0 ), 1 ] );

	t.strictEqual( v, expected, 'returns expected value' );
	t.end();
});

tape( 'the function supports non-unit strides', function test( t ) {
	var expected = 1.0;
	var x = new Float32Array([
		1.0,
		NaN,
		2.0,
		NaN,
		3.0
	]);

	var v = snanstdev( [ vector( x, 3, 2, 0 ), 1 ] );
	t.strictEqual( v, expected, 'returns expected value' );
	t.end();
});

tape( 'the function supports negative strides', function test( t ) {
	var expected = 1.0;
	var x = new Float32Array([
		3.0,
		NaN,
		2.0,
		NaN,
		1.0
	]);

	var v = snanstdev( [ vector( x, 3, -2, 4 ), 1 ] );
	t.strictEqual( v, expected, 'returns expected value' );
	t.end();
});

tape( 'the function supports non-zero offsets', function test( t ) {
	var expected = 1.0;
	var x = new Float32Array([
		NaN,
		1.0,
		NaN,
		2.0,
		NaN,
		3.0
	]);

	var v = snanstdev( [ vector( x, 3, 2, 1 ), 1 ] );
	t.strictEqual( v, expected, 'returns expected value' );
	t.end();
});
